func privateLocationSchema() schema.Schema {
	return schema.Schema{
		Description:         "One of the workspace's own agents, run inside its own network, which checks its monitors there for it alone. Its key is answered once, when it's made, and kept, sensitive.",
		MarkdownDescription: "One of the workspace's own agents, run inside its own network, which checks its monitors there for it alone. Its key is answered once, when it's made, and kept, sensitive.",
		Attributes: map[string]schema.Attribute{
			"created_at": schema.StringAttribute{
				Computed:            true,
				Description:         "An ISO 8601 time in UTC.",
				MarkdownDescription: "An ISO 8601 time in UTC.",
				PlanModifiers: []planmodifier.String{
					stringplanmodifier.UseStateForUnknown(),
				},
			},
			"id": schema.StringAttribute{
				Computed: true,
				PlanModifiers: []planmodifier.String{
					stringplanmodifier.UseStateForUnknown(),
				},
			},
			"key": schema.StringAttribute{
				Computed:            true,
				Sensitive:           true,
				Description:         "`sw_location_<region>_`, the workspace's id as hex, `_` and 48 hex digits: its agent's `SUSTAIN_LOCATION_KEY`.",
				MarkdownDescription: "`sw_location_<region>_`, the workspace's id as hex, `_` and 48 hex digits: its agent's `SUSTAIN_LOCATION_KEY`.",
				PlanModifiers: []planmodifier.String{
					stringplanmodifier.UseStateForUnknown(),
				},
			},
			"key_made_at": schema.StringAttribute{
				Computed:            true,
				Description:         "When its key was made: its agent asks with no other.",
				MarkdownDescription: "When its key was made: its agent asks with no other.",
				PlanModifiers: []planmodifier.String{
					stringplanmodifier.UseStateForUnknown(),
				},
			},
			"key_prefix": schema.StringAttribute{
				Computed:            true,
				Description:         "Enough of its key to tell it from another.",
				MarkdownDescription: "Enough of its key to tell it from another.",
				PlanModifiers: []planmodifier.String{
					stringplanmodifier.UseStateForUnknown(),
				},
			},
			"name": schema.StringAttribute{
				Required: true,
				Validators: []validator.String{
					stringvalidator.LengthBetween(1, 60),
				},
			},
		},
	}
}
